export const getListMetrcPackagesUrl = (params?: ListMetrcPackagesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    const explodeParameters = ["statuses","category_names","item_names","strain_names","ids"];

    if (Array.isArray(value) && explodeParameters.includes(key)) {
      value.forEach((v) => {
        normalizedParams.append(key, v === null ? 'null' : String(v));
      });
      return;
    }

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/public/v1/metrc/packages?${stringifiedParams}` : `/public/v1/metrc/packages`
}

/**
 * Get the Metrc packages Distru caches from Metrc across your licenses, filtered by various attributes. Results are ordered by Metrc's package id ascending and scoped to the company that owns the API key. Only the current version of each package is returned.
 *
 * Each row mirrors a package as it exists in Metrc — label, quantity, item, location, testing and remediation state — plus what Distru knows around it: a derived `status` that reflects the package's real state (Metrc's raw active/inactive buckets don't), the company `unit_type` matching the package's Metrc unit of measure, the full cached Metrc `item`, and `package`, the Distru [package](#model-packagecompact) created when this Metrc package was imported (null when it hasn't been imported). Use `is_importable=true` to list exactly the packages you could import or receive into Distru.
 *
 * This is a read-only cache: it does not create, move, or adjust packages in Metrc. Data is eventually consistent — changes synced from Metrc can take up to ~1 second to appear here.
 * @summary Get Metrc packages
 */
export const listMetrcPackages = async (params?: ListMetrcPackagesParams, options?: Parameters<typeof distruFetch>[1]): Promise<MetrcPackages> => {

  return distruFetch<MetrcPackages>(getListMetrcPackagesUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}



